        .and_then(|path| path.parent())
        .map(|path| path.join("bridge/transform-host.js"))
        .unwrap_or_else(|| PathBuf::from("bridge/transform-host.js"))
}

fn main() -> ExitCode {
    let bridge = bridge_path();
    let status = Command::new(env::var_os("JSCODESHIFT_NODE").unwrap_or_else(|| "node".into()))
        .arg(bridge)
        .args(env::args_os().skip(1))
        .status();

    match status {
        Ok(status) if status.success() => ExitCode::SUCCESS,
        Ok(status) => ExitCode::from(status.code().unwrap_or(1) as u8),
        Err(error) => {
            eprintln!("jscodeshift: failed to start JavaScript transform host: {error}");
            ExitCode::FAILURE
        }
    }
}
