#!/usr/bin/env node
'use strict';

// The JavaScript entrypoint is intentionally limited to locating the native
// dispatcher. The dispatcher runs the compatibility host that loads existing
// JavaScript transforms and their Node ecosystem dependencies.
const childProcess = require('child_process');
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const executable = process.platform === 'win32' ? 'jscodeshift-native.exe' : 'jscodeshift-native';
const candidates = [
  path.join(root, 'native', executable),
  path.join(root, 'rust', 'target', 'release', executable),
];
const launcher = candidates.find(candidate => fs.existsSync(candidate));

if (!launcher) {
  require('../bridge/transform-host');
} else {
  const result = childProcess.spawnSync(launcher, process.argv.slice(2), {
    env: {...process.env, JSCODESHIFT_BRIDGE: path.join(root, 'bridge', 'transform-host.js')},
    stdio: 'inherit',
  });

  if (result.error) {
    throw result.error;
  }
  process.exitCode = result.status === null ? 1 : result.status;
}
